  const EXPENSE_CATEGORIES = ['Travel', 'Mileage', 'Accommodation', 'Subsistence', 'Equipment', 'Training', 'Other'];
  const COURSES = [['Fire Safety Awareness', 'Health & Safety', 90], ['Manual Handling', 'Health & Safety', 120], ['GDPR and Data Protection', 'Compliance', 60], ['Equality, Diversity and Inclusion', 'Compliance', 75], ['Safeguarding Level 1', 'Compliance', 90], ['First Aid at Work', 'Health & Safety', 180], ['Cyber Security Basics', 'Technology', 45]];
  const REQUEST_STATUSES = ['Pending', 'Approved', 'Rejected', 'Cancelled'];
